42	struct DelayedLoadingHeader {
43	    started_at: Instant,
44	    frame_requester: FrameRequester,
45	    animations_enabled: bool,
46	    loading_text: String,
47	    note: Option<String>,
48	}
49	
50	impl DelayedLoadingHeader {
51	    fn new(
52	        frame_requester: FrameRequester,
53	        animations_enabled: bool,
54	        loading_text: String,
55	        note: Option<String>,
56	    ) -> Self {
57	        Self {
58	            started_at: Instant::now(),
59	            frame_requester,
60	            animations_enabled,
61	            loading_text,
62	            note,
63	        }
64	    }
65	}
66	
67	impl Renderable for DelayedLoadingHeader {
68	    fn render(&self, area: Rect, buf: &mut Buffer) {
69	        if area.is_empty() {
70	            return;
71	        }
72	
73	        let mut lines = Vec::with_capacity(3);
74	        lines.push(Line::from("Plugins".bold()));
75	
76	        let now = Instant::now();
77	        let elapsed = now.saturating_duration_since(self.started_at);
78	        if elapsed < LOADING_ANIMATION_DELAY {
79	            self.frame_requester
80	                .schedule_frame_in(LOADING_ANIMATION_DELAY - elapsed);
81	            lines.push(Line::from(self.loading_text.as_str().dim()));
82	        } else if self.animations_enabled {
83	            self.frame_requester
84	                .schedule_frame_in(LOADING_ANIMATION_INTERVAL);
85	            lines.push(Line::from(shimmer_spans(self.loading_text.as_str())));
86	        } else {
87	            lines.push(Line::from(self.loading_text.as_str().dim()));
88	        }
89	
90	        if let Some(note) = &self.note {
91	            lines.push(Line::from(note.as_str().dim()));
92	        }
93	
94	        Paragraph::new(lines).render_ref(area, buf);
95	    }
96	
97	    fn desired_height(&self, _width: u16) -> u16 {
98	        2 + u16::from(self.note.is_some())
99	    }
100	}
