43	/// Horizontal gap (in columns) between the list area and the side content
44	/// panel when side-by-side layout is active.
45	const SIDE_CONTENT_GAP: u16 = 2;
46	
47	/// Shared menu-surface horizontal inset (2 cells per side) used by selection popups.
48	const MENU_SURFACE_HORIZONTAL_INSET: u16 = 4;
49	
50	/// Controls how the side content panel is sized relative to the popup width.
51	///
52	/// When the computed side width falls below `side_content_min_width` or the
53	/// remaining list area would be narrower than [`MIN_LIST_WIDTH_FOR_SIDE`], the
54	/// side-by-side layout is abandoned and the stacked fallback is used instead.
55	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
56	pub(crate) enum SideContentWidth {
57	    /// Fixed number of columns.  `Fixed(0)` disables side content entirely.
58	    Fixed(u16),
59	    /// Exact 50/50 split of the content area (minus the inter-column gap).
60	    Half,
61	}
62	
63	impl Default for SideContentWidth {
64	    fn default() -> Self {
65	        Self::Fixed(0)
66	    }
67	}
