69	/// Returns the popup content width after subtracting the shared menu-surface
70	/// horizontal inset (2 columns on each side).
71	pub(crate) fn popup_content_width(total_width: u16) -> u16 {
72	    total_width.saturating_sub(MENU_SURFACE_HORIZONTAL_INSET)
73	}
