75	/// Returns side-by-side layout widths as `(list_width, side_width)` when the
76	/// layout can fit. Returns `None` when the side panel is disabled/too narrow or
77	/// when the remaining list width would become unusably small.
78	pub(crate) fn side_by_side_layout_widths(
79	    content_width: u16,
80	    side_content_width: SideContentWidth,
81	    side_content_min_width: u16,
82	) -> Option<(u16, u16)> {
83	    let side_width = match side_content_width {
84	        SideContentWidth::Fixed(0) => return None,
85	        SideContentWidth::Fixed(width) => width,
86	        SideContentWidth::Half => content_width.saturating_sub(SIDE_CONTENT_GAP) / 2,
87	    };
88	    if side_width < side_content_min_width {
89	        return None;
90	    }
91	    let list_width = content_width.saturating_sub(SIDE_CONTENT_GAP + side_width);
92	    (list_width >= MIN_LIST_WIDTH_FOR_SIDE).then_some((list_width, side_width))
93	}
