93	fn tab_unit(label: &str, active: bool) -> Vec<Span<'static>> {
94	    if active {
95	        vec![
96	            "[".cyan().bold(),
97	            label.to_string().cyan().bold(),
98	            "]".cyan().bold(),
99	        ]
100	    } else {
101	        vec![label.to_string().dim()]
102	    }
103	}
